from pathlib import Path
import json
from story import S,D
P=Path(__file__).parent
story=[dict(a=a,b=b,kind=k,title=t,body=body,p1=p1,p2=p2) for a,b,k,t,body,p1,p2 in S]
parts=[]
for i,s in enumerate(story):
 nums=s['title'] in ['1519','1521','1700–1200','≈10 000'];side='right' if i%3==1 else 'left';font='date' if nums else ''
 extra='<p class="question">¿Qué historia del cerro conoces?</p>' if i==len(story)-1 else ''
 parts.append(f'<section id="s{i}" class="chapter {side} {font}" style="opacity:{1 if i==0 else 0};z-index:{i+1}"><div class="scene-content"><div class="copy"><h1 class="enter">{s["title"]}</h1><p class="body enter">{s["body"]}</p>{extra}</div><div class="stage-space"><figure class="character"><div class="contact-shadow"></div><div class="character-motion"><img id="p{i}a" class="pose first" src="assets/personaje/variante-{s["p1"]:02d}.png" alt="Personaje original del usuario"><img id="p{i}b" class="pose second" src="assets/personaje/variante-{s["p2"]:02d}.png" alt="Otra postura del personaje original"></div></figure></div></div></section>')
css='''@font-face{font-family:Editorial;src:url(assets/editorial.ttf);font-weight:400}@font-face{font-family:Readable;src:url(assets/body.ttf);font-weight:400}*{box-sizing:border-box}body{margin:0;background:#21102F;color:white;font-family:Readable}#root{position:relative;width:1080px;height:1920px;overflow:hidden;background:#21102F}#room{position:absolute;inset:28px;border-radius:48px;overflow:hidden;background:#4B2D67;box-shadow:0 22px 45px #10051D70;border:1px solid #89679D50}#world{position:absolute;inset:0;width:100%;height:100%;display:block}.chapter{position:absolute;inset:0;pointer-events:none}.scene-content{width:100%;height:100%;display:flex;flex-direction:column;padding:110px 70px 70px;gap:30px}.copy{max-width:880px;position:relative;isolation:isolate;flex:none}.copy h1{font-family:Editorial;font-size:94px;font-weight:400;line-height:1.08;letter-spacing:-.035em;margin:0;max-width:890px;color:#FFFFFF;text-shadow:0 3px 15px #21102F55}.body{font-family:Readable;font-size:46px;font-weight:400;line-height:1.3;margin:25px 0 0;max-width:850px;color:#FFFFFF;text-shadow:0 2px 10px #21102F55}.body:before{content:'';width:55px;height:5px;background:#FFC52B;display:block;margin-bottom:22px;border-radius:5px}.stage-space{position:relative;width:100%;flex:1;min-height:500px}.character{position:absolute;bottom:0;left:-25px;width:420px;height:560px;margin:0;isolation:isolate}.right .character{left:auto;right:-25px;width:405px;height:540px}.character-motion{position:absolute;inset:0;transform-origin:50% 90%;filter:drop-shadow(9px 15px 11px #15082045)}.pose{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;object-position:center bottom;display:block}.pose.second{opacity:0}.contact-shadow{position:absolute;bottom:14px;left:50%;width:235px;height:25px;transform:translateX(-50%);border-radius:50%;background:#180A2966;filter:blur(10px);z-index:-1}.date h1{font-size:172px;line-height:1.07;color:#FFC52B;letter-spacing:-.065em}.date .body{font-size:48px}.question{position:relative;font-size:50px;line-height:1.25;margin:25px 0 0;color:#FFC52B;max-width:850px}#s0 .copy h1{font-size:105px}#s0 .character{width:490px;height:650px}#s2 .copy h1{font-size:87px}#s16 .copy h1{font-size:88px}#s17 h1{font-size:160px}#s35 h1{font-size:103px}'''
js='''const STORY=DATA;const world=createCerroWorld(document.getElementById('world'),STORY);const tl=gsap.timeline({paused:true,onUpdate:()=>world.update(tl.time())});window.__timelines={main:tl};
STORY.forEach((s,i)=>{const q='#s'+i,span=s.b-s.a;
if(i){tl.set(q,{opacity:1},s.a);tl.from(q+' .copy',{x:i%2?-90:90,opacity:0,duration:.72,ease:'power3.out'},s.a+.30);tl.to('#s'+(i-1),{opacity:0,duration:.22,ease:'sine.inOut'},s.a)}
tl.from(q+' h1',{y:40,opacity:0,duration:.7,ease:'expo.out'},s.a+.15);tl.from(q+' .body',{y:25,opacity:0,duration:.62,ease:'sine.out'},s.a+.45);
tl.from(q+' .character',{x:i%3===1?160:-160,opacity:0,rotation:i%3===1?4:-4,duration:.9,ease:'power3.out'},s.a+.3);
tl.to(q+' .character-motion',{y:-6,rotation:.6,duration:1.9,yoyo:true,repeat:Math.max(0,Math.floor((span-1.3)/1.9)-1),ease:'sine.inOut'},s.a+1.3);
const mid=s.a+Math.max(2,span*.51);tl.to(q+' .pose.first',{opacity:0,duration:.2,ease:'sine.inOut'},mid);tl.to(q+' .pose.second',{opacity:1,duration:.2,ease:'sine.inOut'},mid);tl.from(q+' .pose.second',{y:5,scale:.98,duration:.35,ease:'back.out(1.1)'},mid);
if(i===STORY.length-1)tl.from(q+' .question',{y:25,opacity:0,duration:.6,ease:'power3.out'},289.2);
});world.update(0);'''.replace('DATA',json.dumps(story,ensure_ascii=False))
html='<!doctype html><html lang="es"><head><meta charset="UTF-8"><style>'+css+'</style></head><body><div id="root" data-composition-id="main" data-start="0" data-duration="'+str(D)+'" data-width="1080" data-height="1920"><div id="room"><canvas id="world" data-layout-ignore></canvas>'+''.join(parts)+'</div><audio id="voice-original" src="assets/audio-original.wav" data-start="0" data-duration="'+str(D)+'" data-track-index="2" data-volume="0.95"></audio><audio id="soft-effects" src="assets/efectos.wav" data-start="0" data-duration="293.450958" data-track-index="3" data-volume="0.2"></audio></div><script src="assets/three.min.js"></script><script src="assets/gsap.min.js"></script><script src="models.js"></script><script src="world.js"></script><script>'+js+'</script></body></html>'
(P/'index.html').write_text(html);(P/'guion.json').write_text(json.dumps(story,ensure_ascii=False,indent=2))
